<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';
airi_admin_require();
$pdo=airi_db();$flash='';
if(strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'))==='POST'){
    airi_require_csrf();$action=airi_text($_POST['action']??'',30);
    if($action==='add'){
        $version=airi_text($_POST['app_version']??'',32);$channel=airi_text($_POST['channel']??'commercial',32);$hash=airi_hex64($_POST['exe_sha256']??'');$notes=airi_text($_POST['notes']??'',255);$enforce=!empty($_POST['enforce'])?1:0;
        if($version!==''&&$hash!==''){$pdo->prepare("INSERT INTO release_builds(app_version,channel,exe_sha256,status,enforce_integrity,notes) VALUES(?,?,?,'allowed',?,?) ON DUPLICATE KEY UPDATE status='allowed',enforce_integrity=VALUES(enforce_integrity),notes=VALUES(notes)")->execute([$version,$channel,$hash,$enforce,$notes]);airi_admin_audit('release_add','release',$version,['hash_prefix'=>substr($hash,0,16),'enforce'=>$enforce]);$flash='Official build saved.';}else $flash='Version or SHA-256 is invalid.';
    }elseif($action==='update'){
        $id=(int)($_POST['id']??0);$status=airi_text($_POST['status']??'',24);$enforce=!empty($_POST['enforce'])?1:0;if($id>0&&in_array($status,['allowed','revoked'],true)){$pdo->prepare('UPDATE release_builds SET status=?,enforce_integrity=? WHERE id=?')->execute([$status,$enforce,$id]);airi_admin_audit('release_update','release',(string)$id,['status'=>$status,'enforce'=>$enforce]);$flash='Build policy updated.';}
    }
}
$rows=$pdo->query('SELECT * FROM release_builds ORDER BY id DESC LIMIT 200')->fetchAll();
function h2(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AIRI Official Builds</title><style>
:root{--cream:#fff8ea;--blue:#0f4c81;--navy:#17283f;--muted:#607086;--line:#dce6f0;--red:#a12a2a}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--navy);font:14px Segoe UI,system-ui,sans-serif}.wrap{max-width:1200px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;align-items:center}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;margin-top:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}input,select{width:100%;border:1px solid var(--line);border-radius:9px;padding:10px;margin-top:5px}.btn{border:0;border-radius:10px;padding:10px 14px;background:var(--blue);color:#fff;font-weight:700;cursor:pointer}.muted{color:var(--muted)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #edf1f5}.hash{font:12px Consolas,monospace}.flash{padding:10px 12px;background:#edf8f2;border-radius:10px;margin-top:12px}a{color:var(--blue);text-decoration:none}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><b style="color:#0f4c81;letter-spacing:.08em">AIRI TECHNOLOGY</b><h1 style="margin:4px 0">Official Builds</h1><div class="muted">Register trusted executable hashes for tamper/crack detection.</div></div><a href="./?admin=dashboard">← Dashboard</a></div><?php if($flash):?><div class="flash"><?=h2($flash)?></div><?php endif?><div class="card"><h2>Add official build</h2><form method="post"><input type="hidden" name="csrf" value="<?=h2(airi_csrf())?>"><input type="hidden" name="action" value="add"><div class="grid"><label>App version<input name="app_version" placeholder="2.7.0" required></label><label>Channel<input name="channel" value="commercial" required></label></div><label style="display:block;margin-top:12px">AIRI Download Manager.exe SHA-256<input class="hash" name="exe_sha256" maxlength="64" placeholder="64 hexadecimal characters" required></label><label style="display:block;margin-top:12px">Notes<input name="notes" placeholder="GitHub release v2.7.0-license-cloud"></label><label style="display:block;margin:14px 0"><input style="width:auto" type="checkbox" name="enforce" value="1"> Block clients that claim this version but have a different binary hash</label><button class="btn">Save official build</button></form></div><div class="card"><h2>Registered builds</h2><div style="overflow:auto"><table><thead><tr><th>Version</th><th>Channel</th><th>SHA-256</th><th>Status</th><th>Enforce</th><th>Policy</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h2((string)$r['app_version'])?></b></td><td><?=h2((string)$r['channel'])?></td><td class="hash"><?=h2(substr((string)$r['exe_sha256'],0,24))?>…</td><td><?=h2((string)$r['status'])?></td><td><?=(int)$r['enforce_integrity']?'YES':'no'?></td><td><form method="post" style="display:flex;gap:6px;align-items:center"><input type="hidden" name="csrf" value="<?=h2(airi_csrf())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status" style="width:auto"><option value="allowed" <?=$r['status']==='allowed'?'selected':''?>>allowed</option><option value="revoked" <?=$r['status']==='revoked'?'selected':''?>>revoked</option></select><label><input style="width:auto" type="checkbox" name="enforce" value="1" <?=(int)$r['enforce_integrity']?'checked':''?>> enforce</label><button class="btn">Update</button></form></td></tr><?php endforeach?></tbody></table></div></div></div></body></html>
